# -*- coding: utf-8 -*-
"""Learner-facing Vietnamese explanations for M14 reading and Listening."""

EXPLANATIONS = {
    "N2_14_M1_01": "緩和 đọc là かんわ, nghĩa là làm giảm mức căng thẳng hoặc nghiêm trọng. Trong câu, thay đổi giúp tình trạng hỗn loạn dịu xuống nên cách đọc và sắc thái này đều phù hợp.",
    "N2_14_M1_02": "踏まえる đọc là ふまえる, nghĩa là cân nhắc hoặc dựa trên thông tin đã có. Người phụ trách xem xét ý kiến của người sử dụng rồi mới sửa kế hoạch.",
    "N2_14_M1_03": "支障 đọc là ししょう, chỉ trở ngại làm một việc khó tiến hành. Câu nói mưa kéo dài nhưng không gây trở ngại lớn cho việc tổ chức trận đấu.",
    "N2_14_M1_04": "適用 đọc là てきよう, nghĩa là áp dụng quy định vào một trường hợp cụ thể. Chế độ chỉ được áp dụng khi người liên quan đáp ứng các điều kiện đã nêu.",
    "N2_14_M1_05": "考慮 đọc là こうりょ, nghĩa là đưa một yếu tố vào khi suy nghĩ hoặc quyết định. Câu yêu cầu không vội kết luận và phải xét thêm những khả năng khác.",
    "N2_14_M1_55": "Hạn đổi ngày là trước ngày sử dụng ba ngày. Mốc một tháng trước chỉ là lúc bắt đầu nhận đặt phòng, không phải hạn để thay đổi lịch.",
    "N2_14_M1_56": "Biểu mẫu chỉ yêu cầu chọn ngày giờ mong muốn và cách liên lạc. Người đặt không cần viết toàn bộ sự việc; trường hợp khẩn cấp phải gọi điện.",
    "N2_14_M1_57": "Vé vào triển lãm miễn phí, còn khu trải nghiệm thu 200 yên tiền vật liệu. Trẻ nhỏ cần người giám hộ và khách không được chạm vào tác phẩm.",
    "N2_14_M1_58": "Nếu ngày trả rơi vào ngày thư viện đóng cửa, hạn thường được chuyển sang ngày mở cửa kế tiếp. Ngoại lệ là sách đã có người khác đặt trước.",
    "N2_14_M1_59": "Sau sự kiện, hội viên xem được bản ghi trong một tuần và được chép phần trích dẫn vào sổ học cá nhân. Tài liệu không được tải xuống.",
    "N2_14_M1_60": "Tác giả lưu ý rằng gửi tài liệu trước không có nghĩa mọi người đã chuẩn bị xong. Cần chỉ rõ thứ tự đọc và câu hỏi cần xác nhận để cuộc họp tập trung vào quyết định.",
    "N2_14_M1_61": "Hai nhóm có nhu cầu khác nhau: người mới được hướng dẫn quy trình cơ bản, còn người có kinh nghiệm kiểm tra đường sơ tán. Cách tổ chức vì thế phải phù hợp với từng nhóm.",
    "N2_14_M1_62": "Tác giả khuyên chia nội dung chuẩn bị thành phần cần quyết định và phần chỉ cần thông báo. Nhờ vậy, cuộc họp dành thời gian cho thảo luận thay vì đọc lại toàn bộ tài liệu.",
    "N2_14_M1_63": "Buổi bán thử giúp người mở cửa hàng kiểm tra phản ứng khách, còn khu phố xem được cách kinh doanh trước hợp đồng dài hạn. Bài đọc không hứa chắc chắn tăng doanh thu.",
    "N2_14_M1_64": "Để hoạt động tiếp tục sau giai đoạn thử, người bán cần giải thích với hàng xóm và tham gia đời sống địa phương. Chỉ xét doanh số sẽ bỏ qua quan hệ cộng đồng.",
    "N2_14_M1_65": "Tác giả mong muốn tìm cách kinh doanh phù hợp với đặc điểm của khu phố. Bài viết không đề nghị buộc mọi người ký hợp đồng dài hạn hay chọn cùng một loại cửa hàng.",
    "N2_14_M1_66": "Thêm ứng dụng không bảo đảm tin khẩn cấp đến được mọi người vì có nơi mạng yếu và có người bỏ qua quá nhiều thông báo. Đây là giới hạn chính được nêu.",
    "N2_14_M1_67": "Cách nhận tin thuận tiện thay đổi theo nơi ở và thời gian sinh hoạt, không chỉ theo tuổi. Vì thế, người dân cần có nhiều đường để kiểm tra cùng một nội dung.",
    "N2_14_M1_68": "Người viết muốn kết hợp trang mạng hoặc ứng dụng với bảng giấy và mạng lưới khu phố. Cập nhật tại nơi sơ tán cũng cần hiện rõ thời điểm mới nhất.",
    "N2_14_M1_69": "Thư viện A mở muộn nhưng quầy tư vấn đóng lúc 18 giờ. Thư viện B mở đến 21 giờ hai ngày mỗi tuần và vẫn tư vấn, dù sách trong kho cần được đặt trước.",
    "N2_14_M1_70": "Ở thư viện B, sách trong kho không được lấy vào buổi tối nếu chưa đặt. Người đọc cần gửi yêu cầu từ ngày hôm trước để nhân viên chuẩn bị tài liệu.",
    "N2_14_M1_71": "Cân nhắc vận hành sớm giúp giảm nguy cơ tranh cãi sau khi cơ sở hoàn thành và chọn phương án có thể quản lý được. Tác giả không khẳng định chắc chắn giảm chi phí xây dựng.",
    "N2_14_M1_72": "Thành phố gộp những đề xuất phục vụ cùng mục đích rồi tính nhu cầu nhân lực và chi phí trước khi xét lại. Họ không cam kết thực hiện mọi mong muốn ban đầu.",
    "N2_14_M1_73": "Thông điệp là chia sẻ mục tiêu cùng các giới hạn để sắp xếp ưu tiên. Bàn bạc sớm không bảo đảm công trình rẻ hơn, nhưng hỗ trợ quyết định khả thi.",
    "N2_14_M1_74": "Phòng thứ nhất cho ăn nhưng chỉ chứa 20 người; phòng thứ hai chứa đủ 25 người nhưng cấm ăn. Phòng âm nhạc chỉ có 12 chỗ, nên không phòng nào đáp ứng đồng thời hai điều kiện.",
    "N2_14_M1_75": "Máy chiếu được dùng miễn phí nhưng phải đăng ký ngay lúc đặt phòng. Hướng dẫn không yêu cầu trả thêm phí hoặc chỉ định riêng phòng âm nhạc.",
    "N2_14_M1_L01": "Quảng trường đã được nhóm khác đặt trước. Người phụ nữ sẽ hỏi ban quản lý xem khu gần lối đi bộ còn dùng được không, rồi mới nộp đơn xin phép.",
    "N2_14_M1_L02": "Chuyến tàu mong muốn đã hết chỗ. Trước tiên cô ấy cần kiểm tra chuyến sớm hơn để kịp cuộc họp; nếu không được mới xin chuyển sang họp trực tuyến.",
    "N2_14_M1_L03": "Bác sĩ có thể giải thích kết quả từ 14 giờ và bệnh nhân không có triệu chứng khẩn cấp. Vì vậy, cô ấy sẽ đặt lại lịch vào buổi chiều.",
    "N2_14_M1_L04": "Số người đăng ký là 30 nhưng lần trước có thêm khoảng 10 người đến trực tiếp. Người phụ trách chọn in 45 bộ để đủ tài liệu dự phòng.",
    "N2_14_M1_L05": "Khách muốn đổi sang khách sạn gần ga nhưng cần biết mức tăng 3.000 yên mỗi đêm. Cô ấy sẽ xác nhận chi phí rồi mới yêu cầu đổi.",
    "N2_14_M2_L01": "Muốn gia hạn, người dùng phải báo quầy lễ tân trước giờ kết thúc 30 phút. Việc gia hạn chỉ được chấp nhận nếu không có lượt đặt tiếp theo.",
    "N2_14_M2_L02": "Do công trình, xe không dừng ở phố Trung Tâm. Hành khách xuống trước tại tòa thị chính rồi sang điểm tạm ở cửa Bắc; thẻ định kỳ vẫn dùng được.",
    "N2_14_M2_L03": "Nếu số đơn vượt chỗ, ban tổ chức sẽ bốc thăm. Học viên tự chuẩn bị vật liệu và phải báo nghỉ trước một ngày.",
    "N2_14_M2_L04": "Khi vắng nhà, cư dân không được gửi chìa khóa cho phòng quản lý. Họ cần đăng ký một ngày kiểm tra khác.",
    "N2_14_M2_L05": "Đồ quý không được gửi ở quầy giữ hành lý, nên người tham gia phải tự bảo quản. Ban tổ chức chỉ giữ những hành lý thông thường.",
    "N2_14_M2_L06": "Mỗi người được mượn máy tính bảng hai giờ. Có thể gia hạn khi không ai đặt trước; sau khi dùng phải trả tại quầy và không được mang ra ngoài.",
    "N2_14_M3_L01": "Chuyên gia khuyên khảo sát điểm đến, thời gian và mục đích đi lại của cư dân. Chỉ so khoảng cách đến ga hoặc tăng số chuyến xe buýt sẽ không đủ.",
    "N2_14_M3_L02": "Người phụ trách nói xem hết video chưa chứng minh đã học được nội dung. Cần trao đổi cách áp dụng vào công việc và có nơi hỏi sau khóa học.",
    "N2_14_M3_L03": "Tiêu đề cần thu hút người đọc mà không làm họ hiểu sai nội dung bài. Biên tập viên phải kiểm tra cách nêu số liệu và phạm vi sự kiện.",
    "N2_14_M3_L04": "Thêm loại rác mới có thể khiến người dân nhầm hoặc bỏ cuộc nếu hướng dẫn khó hiểu. Thành phố muốn làm rõ cách phân loại trước và kiểm tra khả năng duy trì.",
    "N2_14_M3_L05": "Một khác biệt trong khảo sát chưa chứng minh quan hệ nguyên nhân. Cần nêu đối tượng, thời gian và cách hỏi để giới hạn kết luận chính xác.",
    "N2_14_M4_L01": "Đây là lời nhờ nộp tài liệu trong ngày. Câu đáp phù hợp xác nhận sẽ mang đến trước buổi chiều.",
    "N2_14_M4_L02": "Người nói xin phép mở cửa sổ. Câu đồng ý vì trong phòng hơi nóng đáp ứng đúng yêu cầu.",
    "N2_14_M4_L03": "Câu hỏi xác nhận việc đặt phòng đã xong chưa. Người nghe trả lời đã nhận thư xác nhận vào buổi sáng.",
    "N2_14_M4_L04": "Người hỏi muốn biết vị trí bưu điện gần đây. Hướng dẫn qua đường lớn rồi đi tiếp trả lời đúng câu hỏi địa điểm.",
    "N2_14_M4_L05": "Đây là đề nghị dời giờ họp muộn hơn 30 phút. Câu đáp chấp nhận và hứa báo cho người tham gia phù hợp nhất.",
    "N2_14_M4_L06": "Người nói nhờ chỉ cách dùng máy. Đáp án đồng ý và hướng dẫn bật nguồn là phản hồi trực tiếp.",
    "N2_14_M4_L07": "Câu hỏi là thư báo giá đã đến chưa. Người nghe xác nhận nhận được qua email sáng nay.",
    "N2_14_M4_L08": "Người nói nhờ tham dự buổi giới thiệu thay mình. Câu nhận lời và chuẩn bị tài liệu phù hợp với lời nhờ.",
    "N2_14_M4_L09": "Nhận xét về sự yên tĩnh được đáp lại bằng một nguyên nhân hợp lý: công trình bên cạnh đang nghỉ.",
    "N2_14_M4_L10": "Người hỏi muốn biết phần nào cần sửa. Chỉ dẫn kiểm tra số liệu ở trang ba nêu đúng một việc cụ thể.",
    "N2_14_M4_L11": "Câu hỏi yêu cầu ước lượng thời gian đi bộ tới ga. Trả lời khoảng mười phút cung cấp đúng thông tin được hỏi.",
    "N2_14_M5_L01": "Thông tin chưa công bố phải được tách khỏi báo cáo chung và chỉ cho người phụ trách xem. Báo cáo chính chỉ nêu khái quát, không để lộ tên đối tác hay giá.",
    "N2_14_M5_L02": "Nếu chưa kịp chốt số liệu, hai sinh viên chỉ trình bày phần đã xác nhận và nói rõ phần còn lại đang kiểm tra. Họ cũng không công khai câu trả lời nhận diện được cá nhân.",
    "N2_14_M5_L03": "Khi có cảnh báo gió mạnh, tour chuyển sang tuyến trong thị trấn. Khách muốn hủy phải báo trước giờ xuất phát để nhận lại toàn bộ phí.",
}


def apply_vietnamese_explanations(items):
    for item in items:
        explanation = EXPLANATIONS.get(item.get("id"))
        if explanation:
            item["explanationVi"] = explanation
    return items
